odoo.template:
        'use strict';
        const PWA_CACHE_NAME = '';
        const URL_TO_CACHE = [

              '',

        ];
        self.addEventListener('install', function (ev) {
    // take over right away so an old worker (which cached backend pages) stops controlling tabs
    self.skipWaiting();
          ev.waitUntil(
           caches.open(PWA_CACHE_NAME).then(function (cache) {
               return cache.addAll(URL_TO_CACHE);
           })
          );
        });
        self.addEventListener('activate', function(ev) {
           ev.waitUntil(
               caches.keys().then(function(keyList) {
                   return Promise.all(keyList.map(function(key) {
                       if (key !== PWA_CACHE_NAME) {
                           return caches.delete(key);
                       }
                   }));
               })
           );
          self.clients.claim();
        });
        // Only website assets/images/pages are handled. The backend, RPC/JSON calls, the bus and the
// editor are never intercepted: replaying cached copies of those (e.g. while the server restarts)
// brought back stale sessions / CSRF tokens and showed "session expired" to logged-in users.
function scitaSkip(req) {
    if (req.method !== 'GET' || !req.url.startsWith(self.location.origin)) {
        return true;
    }
    const url = new URL(req.url);
    const path = url.pathname;
    if (url.searchParams.has('debug')) {
        return true;
    }
    if (path === '/web/login' || path.startsWith('/odoo') || path.startsWith('/@/') ||
        path.startsWith('/websocket') || path.startsWith('/longpolling') || path.startsWith('/bus') ||
        path.startsWith('/json') || path.startsWith('/mail/') || path.startsWith('/website/') ||
        path.startsWith('/my') || path.startsWith('/shop/cart') || path.startsWith('/shop/checkout') ||
        path.startsWith('/shop/payment') || path.startsWith('/shop/confirm')) {
        return true;
    }
    // /web/* is backend except static bundles and images
    if (path.startsWith('/web')) {
        const isStatic = ['/web/assets/', '/web/image', '/web/content'].some(function (p) { return path.startsWith(p); });
        return !isStatic;
    }
    return false;
}
self.addEventListener('fetch', function(ev) {
    const req = ev.request;
    if (!req.url.startsWith('http') || scitaSkip(req)) {
        return; // let the browser handle it normally
    }
    if (req.mode === 'navigate') {
        // pages: always from the network (fresh session/CSRF); offline page only when offline
        ev.respondWith(
            fetch(req).catch(function () {
                // online but the request failed (server restarting...): not the offline page
                if (navigator.onLine) {
                    return Response.error();
                }
                return caches.open(PWA_CACHE_NAME).then(function (cache) {
                    return cache.match('/theme_scita/pwa/offline');
                }).then(function (res) {
                    return res || Response.error();
                });
            })
        );
        return;
    }
    // static assets / images: network first, cache as fallback
    ev.respondWith(
        fetch(req)
        .then(function(res) {
            if (res ? (res.status === 200 ? res.type === 'basic' : false) : false) {
                const resToCache = res.clone();
                caches.open(PWA_CACHE_NAME).then(function(cache) {
                    cache.put(req, resToCache);
                });
            }
            return res;
        })
        .catch(function() {
            return caches.open(PWA_CACHE_NAME).then(function(cache) {
                return cache.match(req);
            }).then(function (res) {
                // aborted or offline with nothing cached: a plain network error, never undefined
                return res || Response.error();
            });
        })
    );
});
